const fs = require('node:fs');
const path = require('node:path');
const net = require('node:net');
const repo = '/home/jyarwood/workspace/pi-dish-r9';
require(repo + '/test/test-env.js').applyTestEnv();
const home = path.join(__dirname, 'home');
process.env.HOME = home;
process.env.TMUX_TMPDIR = path.join(home, 'tmux');
process.env.PI_DISH_INDEX_SYNC_BUDGET = '1000';
process.env.PI_DISH_HEADLESS = 'rpc';
process.env.PI_DISH_PI_COMMAND = process.execPath + ' ' + repo + '/test/fixtures/fake-rpc-pi.js';
const sessions = path.join(home, '.pi/agent/sessions/project');
const registry = path.join(home, '.pi/dish/sessions');
for (const dir of [sessions, registry, process.env.TMUX_TMPDIR]) fs.mkdirSync(dir, { recursive: true });
const cwd = path.join(home, 'workspace'); fs.mkdirSync(cwd);
for (const id of ['r9-first', 'r9-second']) fs.writeFileSync(path.join(sessions, id + '.jsonl'), [
  {type:'session', cwd, timestamp:'2026-09-16T00:00:00.000Z'},
  {type:'message', message:{role:'user', content:id + ' retained transcript'}},
  {type:'message', message:{role:'assistant', content:[{type:'text', text:'Retirement proof for **' + id + '**.\n\n```js\nconst retained = true;\n```'}]}}
].map(JSON.stringify).join('\n') + '\n');
const bridge = net.createServer(socket => {
  socket.on('error', () => {});
  socket.write(JSON.stringify({type:'hello', turnInProgress:false, queue:{steering:[],followUp:[]}}) + '\n');
  let buffer='';
  socket.on('data', chunk => { buffer += chunk; let end; while ((end=buffer.indexOf('\n'))>=0) {
    const message=JSON.parse(buffer.slice(0,end)); buffer=buffer.slice(end+1);
    const data=message.command==='get_available_models'?{models:[]}:message.command==='get_commands'?[]:{};
    socket.write(JSON.stringify({type:'response',id:message.id,success:true,data})+'\n');
  }});
});
const socketPath=path.join(home,'bridge.sock');
bridge.listen(socketPath,()=>{
  fs.writeFileSync(path.join(registry,'r9-first.json'),JSON.stringify({sessionId:'r9-first',sessionFile:path.join(sessions,'r9-first.jsonl'),socketPath,pid:process.pid,cwd,name:'R9 live first'}));
  const server=require(repo+'/server.js');
  const ready=()=>console.log('R9_READY http://127.0.0.1:'+server.address().port);
  if(server.listening) ready(); else server.once('listening',ready);
});

