'use strict';
const fs = require('node:fs');
const path = require('node:path');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const root = '/home/jyarwood/workspace/pi-dish';
const commands = [
  ['npm', 'run', 'check'],
  ['npm', 'test'],
  ['npm', 'run', 'test:browser'],
  ['npm', 'run', 'test:ui:scenarios'],
  ['npm', 'run', 'test:ui'],
];
const results = { root, integrationBase: 'b570618', reviewedSource: '7282718f6c25ec69a98186a59bf8fdf6c5de5700', node: process.version, platform: process.platform, commands: [] };
for (let i = 0; i < commands.length; i++) {
  const [command, ...args] = commands[i];
  const log = path.join(__dirname, `gate-${i + 1}.log`);
  const fd = fs.openSync(log, 'w');
  const started = new Date().toISOString();
  const start = performance.now();
  const result = cp.spawnSync(command, args, { cwd: root, stdio: ['ignore', fd, fd], timeout: 900000 });
  fs.closeSync(fd);
  const bytes = fs.readFileSync(log);
  const entry = { command: [command, ...args].join(' '), started, seconds: (performance.now() - start) / 1000, exitCode: result.status, signal: result.signal, error: result.error?.message, log, logBytes: bytes.length, sha256: crypto.createHash('sha256').update(bytes).digest('hex') };
  results.commands.push(entry);
  fs.writeFileSync(path.join(__dirname, 'gates-result.json'), JSON.stringify(results, null, 2) + '\n');
  console.log(JSON.stringify(entry));
  console.log(bytes.toString('utf8').split('\n').slice(-14).join('\n'));
  if (result.status !== 0) process.exit(result.status || 1);
}
